def handle(app, svc):
    res = svc.apply(app)
    decision = res.get("decision")
    limit = res.get("limit", 0)

    if decision == "refer":
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 4000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}

    # decline
    return {"action": "decline", "limit": 0}
